// The O*NET field the shipped scenes draw on: all snapshot occupations with
// their measured RIASEC profiles, and a client-side mirror of the backend's
// grounding path (engine/riasec.js → rankDirections, engine/onet.js →
// rankOccupations). The session snapshot carries the user's scores and each
// output's SOC, but not the shortlist the pick was made from — so the scenes
// re-derive it here from the same data with the same rules. onetField.test.js
// pins both the data and the ranking to the backend.
//
// The data is a separate lazy chunk (data/onet-field.json, generated by
// frontend/scripts/build-onet-field.cjs): reference data, the same for every
// user, never fetched unless a scene needs it.
import { useEffect, useState } from "react";

export const RIASEC_KEYS = ["R", "I", "A", "S", "E", "C"];

// Compact rows → objects, plus the lookups the scenes need.
export function decodeField(raw) {
  const occupations = raw.occupations.map((row) => {
    const [soc, title, ...rest] = row;
    const riasec = Object.fromEntries(raw.riasecKeys.map((k, i) => [k, rest[i]]));
    return { soc, title, riasec, directionId: raw.directions[rest[raw.riasecKeys.length]]?.id ?? null };
  });
  const labels = new Map(raw.directions.map((d) => [d.id, d.label]));
  return {
    version: raw.version,
    attribution: raw.attribution,
    directions: raw.directions,
    occupations,
    bySoc: new Map(occupations.map((o) => [o.soc, o])),
    directionLabel: (id) => labels.get(id) ?? id ?? "",
  };
}

// Pearson correlation — profile shape, insensitive to elevation. Zero variance
// on either side carries no shape signal → 0. Mirror of backend onet.pearson.
export function pearson(a, b) {
  const n = a.length;
  const meanA = a.reduce((s, v) => s + v, 0) / n;
  const meanB = b.reduce((s, v) => s + v, 0) / n;
  let cov = 0;
  let varA = 0;
  let varB = 0;
  for (let i = 0; i < n; i += 1) {
    const da = a[i] - meanA;
    const db = b[i] - meanB;
    cov += da * db;
    varA += da * da;
    varB += db * db;
  }
  if (varA === 0 || varB === 0) return 0;
  return cov / Math.sqrt(varA * varB);
}

// Field families against the interest scores, high to low (weighted dot
// product, rounded; ties keep catalog order). Mirror of riasec.rankDirections.
export function rankDirections(field, riasecScores, { excludeIds = [] } = {}) {
  const excluded = new Set(excludeIds);
  return field.directions
    .filter((d) => !excluded.has(d.id))
    .map((d) => {
      let score = 0;
      for (const [key, weight] of Object.entries(d.weights)) {
        score += weight * (riasecScores?.[key] ?? 50);
      }
      return { id: d.id, label: d.label, score: Math.round(score) };
    })
    .sort((a, b) => b.score - a.score);
}

// Occupations by Pearson r against the interest scores, high to low; ties
// break on SOC. Mirror of onet.rankOccupations.
export function rankOccupations(field, riasecScores, { directionIds, excludeSocs = [], limit = 15 } = {}) {
  const user = RIASEC_KEYS.map((k) => riasecScores?.[k] ?? 50);
  const families = directionIds ? new Set(directionIds) : null;
  const excluded = new Set(excludeSocs);
  return field.occupations
    .filter((o) => !excluded.has(o.soc) && (!families || families.has(o.directionId)))
    .map((o) => ({
      soc: o.soc,
      title: o.title,
      directionId: o.directionId,
      r: pearson(user, RIASEC_KEYS.map((k) => o.riasec[k] ?? 0)),
    }))
    .sort((a, b) => b.r - a.r || (a.soc < b.soc ? -1 : 1))
    .slice(0, limit);
}

export const FAMILY_COUNT = 5;
export const SHORTLIST_SIZE = 15;

// What the backend looks at for one output: the five best families not ruled
// out yet, and the 15 closest unused occupations inside them. `priorOutputs`
// are the outputs generated before the one being explained.
export function groundingFor(field, riasecScores, priorOutputs = []) {
  const usedDirections = priorOutputs.map((o) => o.directionId).filter(Boolean);
  const usedSocs = priorOutputs.map((o) => o.socCode).filter(Boolean);
  const topDirections = rankDirections(field, riasecScores, { excludeIds: usedDirections }).slice(
    0,
    FAMILY_COUNT
  );
  const shortlist = rankOccupations(field, riasecScores, {
    directionIds: topDirections.map((d) => d.id),
    excludeSocs: usedSocs,
    limit: SHORTLIST_SIZE,
  });
  return { topDirections, shortlist };
}

// True when every output shown so far can be placed on the map.
export function canPlaceOutputs(field, outputs) {
  return Boolean(field && outputs.length && outputs.every((o) => o.socCode && field.bySoc.has(o.socCode)));
}

let fieldPromise = null;

// One load per page, shared by every scene.
export function loadOnetField() {
  fieldPromise ??= import("./data/onet-field.json").then((mod) => decodeField(mod.default));
  return fieldPromise;
}

// The decoded field, or null while it loads (and if the chunk fails — scenes
// then fall back to their plain state; nothing in the flow waits on this).
export function useOnetField(enabled = true) {
  const [field, setField] = useState(null);
  useEffect(() => {
    if (!enabled || field) return undefined;
    let alive = true;
    loadOnetField().then(
      (loaded) => alive && setField(loaded),
      () => {
        fieldPromise = null; // let a later mount retry
      }
    );
    return () => {
      alive = false;
    };
  }, [enabled, field]);
  return field;
}
